function ParceiroModal({open,onClose,up,editItem}){const T=useContext(ThemeCtx);const blank={nome:"",tipo:"Institucional",cpfCnpj:"",nomeContato:"",email:"",telefone:"",endereco:"",cidade:"",estado:"",cep:"",status:"Ativo",descricao:""};const[f,sF]=useState(blank);const s=k=>e=>sF(p=>({...p,[k]:e.target.value}));const tipoOpts=["Institucional","Empresarial","Governamental","ONG","Acadêmico","Outro"].map(v=>({value:v,label:v}));const isE=!!editItem;useEffect(()=>{if(open)sF(editItem?{...blank,...editItem}:blank)},[open,editItem]);const go=()=>{if(!f.nome)return;if(isE)up(p=>({...p,parceiros:(p.parceiros||[]).map(x=>x.id===editItem.id?{...x,...f}:x)}));else up(p=>({...p,parceiros:[...(p.parceiros||[]),{...f,id:gid()}]}));onClose()};return(<Modal open={open} onClose={onClose} title={isE?"Editar Parceiro":"Novo Parceiro"}><div style={{display:"flex",flexDirection:"column",gap:12}}><Inp label="Nome/Razão Social *" value={f.nome} onChange={s("nome")}/><div style={{display:"flex",gap:10}}><Sel label="Tipo" value={f.tipo} onChange={s("tipo")} options={tipoOpts}/><Sel label="Status" value={f.status} onChange={s("status")} options={[{value:"Ativo",label:"Ativo"},{value:"Inativo",label:"Inativo"}]}/></div><Inp label="Contato" value={f.nomeContato} onChange={s("nomeContato")}/><div style={{display:"flex",gap:10}}><Inp label="E-mail" value={f.email} onChange={s("email")}/><Inp label="Telefone" value={f.telefone} onChange={s("telefone")}/></div><Inp label="Endereço" value={f.endereco} onChange={s("endereco")}/><div style={{display:"flex",gap:10}}><Inp label="Cidade" value={f.cidade} onChange={s("cidade")}/><Sel label="UF" value={f.estado} onChange={s("estado")} options={UF_OPTS}/></div><Txt label="Descrição" value={f.descricao} onChange={s("descricao")}/><Btn onClick={go} accent={T.blue}>{isE?"Atualizar":"Salvar"}</Btn></div></Modal>)}

function DocModal({open,onClose,up,editItem}){const T=useContext(ThemeCtx);const blank={titulo:"",categoria:"Ata",data:today(),descricao:"",conteudo:"",link:""};const[f,sF]=useState(blank);const s=k=>e=>sF(p=>({...p,[k]:e.target.value}));const catOpts=["Ata","Contrato","Financeiro","Planejamento","Comunicação","Jurídico","Outro"].map(v=>({value:v,label:v}));const isE=!!editItem;useEffect(()=>{if(open)sF(editItem?{...blank,...editItem}:blank)},[open,editItem]);const go=()=>{if(!f.titulo)return;if(isE)up(p=>({...p,documentos:(p.documentos||[]).map(d=>d.id===editItem.id?{...d,...f}:d)}));else up(p=>({...p,documentos:[...(p.documentos||[]),{...f,id:gid()}]}));onClose()};return(<Modal open={open} onClose={onClose} title={isE?"Editar Documento":"Novo Documento"}><div style={{display:"flex",flexDirection:"column",gap:12}}><Inp label="Título *" value={f.titulo} onChange={s("titulo")}/><div style={{display:"flex",gap:10}}><Sel label="Categoria" value={f.categoria} onChange={s("categoria")} options={catOpts}/><Inp label="Data" type="date" value={f.data} onChange={s("data")}/></div><Inp label="Link externo" value={f.link} onChange={s("link")} placeholder="https://drive.google.com/..."/><Txt label="Descrição" value={f.descricao} onChange={s("descricao")}/><Txt label="Conteúdo" value={f.conteudo} onChange={s("conteudo")}/><Btn onClick={go} accent={T.orange}>{isE?"Atualizar":"Arquivar"}</Btn></div></Modal>)}

function LeadModal({open,onClose,up,editItem}){const T=useContext(ThemeCtx);const blank={empresa:"",contato:"",email:"",telefone:"",data:today(),abordagem:"E-mail",status:"Novo",retorno:"",notas:""};const[f,sF]=useState(blank);const s=k=>e=>sF(p=>({...p,[k]:e.target.value}));const abordOpts=["E-mail","Telefone","WhatsApp","Reunião presencial","Evento/Networking","Indicação","Redes sociais","Outro"].map(v=>({value:v,label:v}));const statusOpts=["Novo","Em contato","Proposta enviada","Negociando","Fechado","Perdido"].map(v=>({value:v,label:v}));const isE=!!editItem;useEffect(()=>{if(open)sF(editItem?{...blank,...editItem}:blank)},[open,editItem]);const go=()=>{if(!f.empresa||!f.contato)return;if(isE)up(p=>({...p,leads:(p.leads||[]).map(l=>l.id===editItem.id?{...l,...f}:l)}));else up(p=>({...p,leads:[...(p.leads||[]),{...f,id:gid()}]}));onClose()};return(<Modal open={open} onClose={onClose} title={isE?"Editar Lead":"Novo Lead"}><div style={{display:"flex",flexDirection:"column",gap:12}}><Inp label="Empresa *" value={f.empresa} onChange={s("empresa")}/><Inp label="Contato *" value={f.contato} onChange={s("contato")}/><div style={{display:"flex",gap:10}}><Inp label="E-mail" value={f.email} onChange={s("email")}/><Inp label="Telefone" value={f.telefone} onChange={s("telefone")}/></div><div style={{display:"flex",gap:10}}><Inp label="Data" type="date" value={f.data} onChange={s("data")}/><Sel label="Abordagem" value={f.abordagem} onChange={s("abordagem")} options={abordOpts}/></div><div style={{display:"flex",gap:10}}><Sel label="Status" value={f.status} onChange={s("status")} options={statusOpts}/><Inp label="Retorno" type="date" value={f.retorno} onChange={s("retorno")}/></div><Txt label="Notas" value={f.notas} onChange={s("notas")}/><Btn onClick={go} accent={T.purple}>{isE?"Atualizar":"Cadastrar"}</Btn></div></Modal>)}

// ── MAPA DA INOVAÇÃO ──
const PA_LOCATIONS=[{label:"Centro",lat:-22.2299,lng:-45.9342},{label:"Fátima",lat:-22.2200,lng:-45.9400},{label:"São Geraldo",lat:-22.2350,lng:-45.9250},{label:"São João",lat:-22.2150,lng:-45.9300},{label:"Santa Lúcia",lat:-22.2400,lng:-45.9400},{label:"São Carlos",lat:-22.2380,lng:-45.9200},{label:"Medicina",lat:-22.2450,lng:-45.9350},{label:"Distrito Industrial",lat:-22.2100,lng:-45.9150},{label:"Jardim Panorama",lat:-22.2180,lng:-45.9500},{label:"Colinas",lat:-22.2050,lng:-45.9450},{label:"Outro (informar)",lat:0,lng:0}];
const PROJ_CATS=["Tecnologia","Sustentabilidade","Educação","Saúde","Agronegócio","Indústria 4.0","Economia Criativa","Impacto Social","Inovação Aberta","Outro"];
const PROJ_STATUS=["Em desenvolvimento","Ativo","Concluído","Pausado"];

function MapaInovacao({data,up,openModal}){const T=useContext(ThemeCtx);const user=useContext(UserCtx);const ed=canEditAll(user);const mapRef=useRef(null);const mapInst=useRef(null);const markersRef=useRef([]);const projetos=data.projetos||[];const rm=id=>up(p=>({...p,projetos:(p.projetos||[]).filter(x=>x.id!==id)}));
const[sel,setSel]=useState(null);

useEffect(()=>{if(!document.getElementById("leaflet-css")){const lk=document.createElement("link");lk.id="leaflet-css";lk.rel="stylesheet";lk.href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css";document.head.appendChild(lk)}
const load=()=>new Promise(r=>{if(window.L){r();return}const s=document.createElement("script");s.src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js";s.onload=r;document.body.appendChild(s)});
load().then(()=>{if(!mapRef.current||mapInst.current)return;const m=window.L.map(mapRef.current).setView([-22.2299,-45.9342],13);window.L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png",{attribution:"© OpenStreetMap"}).addTo(m);mapInst.current=m;setTimeout(()=>m.invalidateSize(),200)});
return()=>{if(mapInst.current){mapInst.current.remove();mapInst.current=null}}},[]);

useEffect(()=>{if(!mapInst.current||!window.L)return;markersRef.current.forEach(m=>m.remove());markersRef.current=[];
const icon=window.L.divIcon({className:"",html:'<div style="font-size:28px;filter:drop-shadow(0 2px 4px rgba(0,0,0,.5))">💡</div>',iconSize:[28,28],iconAnchor:[14,28],popupAnchor:[0,-28]});
projetos.forEach(p=>{if(!p.lat||!p.lng)return;const mk=window.L.marker([p.lat,p.lng],{icon}).addTo(mapInst.current);mk.bindPopup('<div style="font-family:Outfit,sans-serif;min-width:180px"><strong style="font-size:14px">'+p.nome+'</strong><br/><span style="color:#666;font-size:12px">'+p.empresa+'</span><br/><span style="background:#1ABC9C22;color:#1ABC9C;padding:1px 8px;border-radius:10px;font-size:11px;font-weight:600">'+p.categoria+'</span><br/><span style="font-size:12px;color:#888">'+p.status+'</span></div>');mk.on("click",()=>setSel(p));markersRef.current.push(mk)})},[projetos]);

const stColor={"Em desenvolvimento":T.orange,"Ativo":T.success,"Concluído":T.blue,"Pausado":T.textMuted};
return(<div><div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:18,flexWrap:"wrap",gap:8}}><h2 style={{margin:0,fontSize:22,fontWeight:800}}>💡 Mapa da Inovação</h2>{ed&&<Btn onClick={()=>openModal("projeto")} accent={T.cyan}>＋ Novo Projeto</Btn>}</div>
<div style={{background:T.card,border:"1px solid "+T.border,borderRadius:16,overflow:"hidden",marginBottom:20}}>
<div ref={mapRef} style={{width:"100%",height:420}}/>
</div>
<div style={{display:"flex",gap:8,marginBottom:14,flexWrap:"wrap"}}><Badge color={T.cyan}>💡 {projetos.length} projetos mapeados</Badge>{PROJ_STATUS.map(s=>{const ct=projetos.filter(p=>p.status===s).length;return ct>0&&<Badge key={s} color={stColor[s]||T.textMuted}>{s}: {ct}</Badge>})}</div>
{sel&&<div style={{background:T.card,border:"2px solid "+T.cyan,borderRadius:16,padding:22,marginBottom:16}}><div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start"}}><div><div style={{fontWeight:800,fontSize:18,color:T.text}}>💡 {sel.nome}</div><div style={{fontSize:13,color:T.textMuted,marginTop:4}}>🏢 {sel.empresa}{sel.responsavel?" · 👤 "+sel.responsavel:""}</div><div style={{display:"flex",gap:6,marginTop:6,flexWrap:"wrap"}}><Badge color={T.cyan}>{sel.categoria}</Badge><Badge color={stColor[sel.status]||T.textMuted}>{sel.status}</Badge>{sel.bairro&&<Badge color={T.textMuted}>📍 {sel.bairro}</Badge>}</div>{sel.descricao&&<div style={{fontSize:14,color:T.text,marginTop:10,lineHeight:1.6}}>{sel.descricao}</div>}{sel.impacto&&<div style={{fontSize:13,color:T.success,marginTop:6}}>🌱 <strong>Impacto:</strong> {sel.impacto}</div>}{sel.contato&&<div style={{fontSize:12,color:T.textMuted,marginTop:4}}>📧 {sel.contato}</div>}</div><span onClick={()=>setSel(null)} style={{cursor:"pointer",color:T.textMuted,fontSize:18}}>✕</span></div></div>}
{projetos.length===0?<div style={{background:T.card,border:"1px solid "+T.border,borderRadius:16,padding:36,textAlign:"center",color:T.textMuted}}>Nenhum projeto cadastrado. {ed?"Clique em '＋ Novo Projeto' para adicionar o primeiro!":"Projetos de inovação aparecerão aqui."}</div>:
<div style={{display:"flex",flexDirection:"column",gap:10}}>{projetos.map(p=>(<div key={p.id} onClick={()=>{setSel(p);if(mapInst.current&&p.lat&&p.lng)mapInst.current.setView([p.lat,p.lng],15)}} style={{background:sel?.id===p.id?T.cyan+"15":T.card,border:sel?.id===p.id?"1px solid "+T.cyan:"1px solid "+T.border,borderRadius:14,padding:"14px 18px",cursor:"pointer",transition:"all .2s"}}><div style={{display:"flex",justifyContent:"space-between",alignItems:"center",flexWrap:"wrap",gap:8}}><div style={{flex:1,minWidth:200}}><div style={{fontWeight:700,fontSize:15}}>💡 {p.nome}</div><div style={{fontSize:12,color:T.textMuted,marginTop:3}}>🏢 {p.empresa}{p.bairro?" · 📍 "+p.bairro:""}</div></div><div style={{display:"flex",gap:6,alignItems:"center",flexWrap:"wrap"}}><Badge color={T.cyan}>{p.categoria}</Badge><Badge color={stColor[p.status]||T.textMuted}>{p.status}</Badge>{ed&&<><span onClick={e=>{e.stopPropagation();openModal("projeto",p)}} style={{cursor:"pointer",color:T.blue,fontSize:14}}>✏️</span><span onClick={e=>{e.stopPropagation();rm(p.id)}} style={{cursor:"pointer",color:T.textMuted}}>🗑️</span></>}</div></div></div>))}</div>}
</div>)}

function ProjetoModal({open,onClose,up,editItem}){const T=useContext(ThemeCtx);const blank={nome:"",empresa:"",responsavel:"",contato:"",categoria:"Tecnologia",status:"Em desenvolvimento",bairro:"Centro",lat:-22.2299,lng:-45.9342,descricao:"",impacto:"",dataInicio:today()};const[f,sF]=useState(blank);const s=k=>e=>sF(p=>({...p,[k]:e.target.value}));const isE=!!editItem;const catOpts=PROJ_CATS.map(v=>({value:v,label:v}));const stOpts=PROJ_STATUS.map(v=>({value:v,label:v}));const locOpts=PA_LOCATIONS.map(l=>({value:l.label,label:l.label}));
useEffect(()=>{if(open)sF(editItem?{...blank,...editItem}:blank)},[open,editItem]);
const handleLoc=e=>{const v=e.target.value;const loc=PA_LOCATIONS.find(l=>l.label===v);sF(p=>({...p,bairro:v,lat:loc?.lat||p.lat,lng:loc?.lng||p.lng}))};
const go=()=>{if(!f.nome||!f.empresa)return;const item={...f,lat:Number(f.lat)||0,lng:Number(f.lng)||0};if(isE)up(p=>({...p,projetos:(p.projetos||[]).map(x=>x.id===editItem.id?{...x,...item}:x)}));else up(p=>({...p,projetos:[...(p.projetos||[]),{...item,id:gid()}]}));onClose()};
return(<Modal open={open} onClose={onClose} title={isE?"Editar Projeto":"💡 Novo Projeto de Inovação"}><div style={{display:"flex",flexDirection:"column",gap:12}}>
<Inp label="Nome do Projeto *" value={f.nome} onChange={s("nome")} placeholder="Ex: Hub de Impressão 3D"/>
<Inp label="Empresa/Instituição *" value={f.empresa} onChange={s("empresa")} placeholder="Nome da empresa ou instituição"/>
<div style={{display:"flex",gap:10}}><Inp label="Responsável" value={f.responsavel} onChange={s("responsavel")} placeholder="Nome do responsável"/><Inp label="Contato" value={f.contato} onChange={s("contato")} placeholder="E-mail ou telefone"/></div>
<div style={{display:"flex",gap:10}}><Sel label="Categoria" value={f.categoria} onChange={s("categoria")} options={catOpts}/><Sel label="Status" value={f.status} onChange={s("status")} options={stOpts}/></div>
<div style={{display:"flex",gap:10}}><Sel label="📍 Bairro/Região" value={f.bairro} onChange={handleLoc} options={locOpts}/><Inp label="Data de Início" type="date" value={f.dataInicio} onChange={s("dataInicio")}/></div>
{f.bairro==="Outro (informar)"&&<div style={{display:"flex",gap:10}}><Inp label="Latitude" type="number" step="0.0001" value={f.lat} onChange={s("lat")}/><Inp label="Longitude" type="number" step="0.0001" value={f.lng} onChange={s("lng")}/></div>}
<Txt label="Descrição do Projeto" value={f.descricao} onChange={s("descricao")} placeholder="O que é o projeto? Qual problema resolve? Qual a inovação envolvida?"/>
<Txt label="🌱 Impacto Esperado/Alcançado" value={f.impacto} onChange={s("impacto")} placeholder="Empregos gerados, pessoas impactadas, resultados..."/>
<Btn onClick={go} accent={T.cyan}>{isE?"Atualizar Projeto":"Cadastrar Projeto"}</Btn>
</div></Modal>)}
